const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon roughly covering a section of the North Crimean Canal in Ukraine.
  // This section is chosen as an example where water extent changes would be visible.
  const canalGeometry = ee.Geometry.Polygon(
    [[[33.15, 46.20],
      [33.25, 46.20],
      [33.25, 46.22],
      [33.15, 46.22],
      [33.15, 46.20]]]
  );

  const date1Start = '2023-06-01';
  const date1End = '2023-06-05'; // Centered around June 3
  const date2Start = '2023-07-17';
  const date2End = '2023-07-21'; // Centered around July 19

  const scale = 10; // Sentinel-2 B3 (Green) and B8 (NIR) are 10m bands

  // Function to mask clouds in Sentinel-2 images using QA60 band.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B3', 'B8']) // Only select bands needed for NDWI
      .copyProperties(image, ['system:time_start', 'CLOUD_PIXEL_PERCENTAGE']);
  }

  // Function to calculate NDWI.
  function calculateNDWI(image) {
    return image.normalizedDifference(['B3', 'B8']).rename('NDWI');
  }

  async function getImageAndWaterArea(dateStart, dateEnd, label) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(canalGeometry)
      .filterDate(dateStart, dateEnd)
      .filter(ee.Filter.lt('CLOUD_PIXEL_PERCENTAGE', 20)); // Filter for relatively clear images

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      // Try expanding the date range slightly if no images are found
      console.log(`No images found for ${label} with current filters. Expanding date range.`);
      const expandedStart = ee.Date(dateStart).advance(-3, 'day').format('YYYY-MM-DD').getInfo();
      const expandedEnd = ee.Date(dateEnd).advance(3, 'day').format('YYYY-MM-DD').getInfo();
      console.log(`Trying expanded range: ${expandedStart} to ${expandedEnd}`);
      collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(canalGeometry)
        .filterDate(expandedStart, expandedEnd)
        .filter(ee.Filter.lt('CLOUD_PIXEL_PERCENTAGE', 20));
    }

    const finalSize = await collection.size().getInfo();
    if (finalSize === 0) {
      console.log(`${label} Images: 0`);
      return { image: null, waterArea: null, cloudPercentage: null };
    }

    // Sort by cloud percentage and get the least cloudy image.
    const image = collection.map(maskS2clouds).median(); // Using median to mosaic available images

    const cloudPixelPercentage = await collection.sort('CLOUD_PIXEL_PERCENTAGE').first().get('CLOUD_PIXEL_PERCENTAGE').getInfo();

    // Calculate NDWI
    const ndwi = calculateNDWI(image);

    // Identify water pixels (NDWI > 0)
    const waterMask = ndwi.gt(0);

    // Count water pixels within the canal geometry
    const waterPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: canalGeometry,
      scale: scale,
      maxPixels: 1e9
    });

    const pixelCount = await waterPixels.get('NDWI').getInfo(); // NDWI is the band name after reduceRegion

    if (pixelCount === null || pixelCount === undefined) {
        return { image: image, waterArea: null, cloudPercentage: cloudPixelPercentage, pixels: 0 }; // Indicate calculation failure for pixels
    }

    const areaSqM = pixelCount * (scale * scale);
    const areaSqKm = areaSqM / 1e6;

    console.log(`${label} Images: ${finalSize} (Cloud %: ${cloudPixelPercentage.toFixed(2)}), Water Pixels: ${Math.round(pixelCount)}, Water Area: ${areaSqKm.toFixed(2)} km²`);

    return { image: image, waterArea: areaSqKm, cloudPercentage: cloudPixelPercentage, pixels: pixelCount };
  }

  try {
    const result1 = await getImageAndWaterArea(date1Start, date1End, 'June 3, 2023');
    const result2 = await getImageAndWaterArea(date2Start, date2End, 'July 19, 2023');

    if (result1.image === null || result2.image === null) {
      console.log('C1: Empty Collection (No images found for one or both comparison points, even after expanding date range).');
      console.log('C1');
      return;
    }

    if (result1.pixels === 0 || result2.pixels === 0) {
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 water pixels remain).');
      console.log('C2');
      return;
    }

    if (result1.waterArea === null || result2.waterArea === null || isNaN(result1.waterArea) || isNaN(result2.waterArea)) {
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      console.log('C3');
      return;
    }

    if (result2.waterArea < result1.waterArea) {
      console.log('A'); // Yes
    } else {
      console.log('B'); // No
    }

  } catch (e) {
    console.error('An error occurred during analysis: ', e);
    console.log('D'); // General error / Calculation failure
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
